-- Window & Layer Rules — Hyprland 0.55 (legacy hyprlang format)

-- =============================================================================

-- Syntax reference (0.55 legacy .conf):

--   windowrule = <effect> <value>, match:<prop> <regex>[, match:<prop> <regex>, ...]

--   windowrule = <effect> <value>[, <effect> <value>, ...]

--

-- Effects and matchers are comma-separated tokens. Each token is split on the

-- FIRST space: left side = effect name OR "match:<prop>", right = value/regex.

-- Effects: float, tile, center, size, pin, opacity, workspace, idle_inhibit,

--          no_initial_focus, keep_aspect_ratio, immediate, move, monitor, etc.

-- Boolean effects (float, center, pin, keep_aspect_ratio, immediate, ...):

--   value must be "true"/"false"/"1"/"0" — e.g. "float true", "center true"

-- Matchers: match:class, match:title, match:initial_class, match:initial_title,

--           match:modal, match:float, match:xwayland, match:fullscreen, etc.

-- Rule order: all matching rules are applied in file order; LAST rule wins per

--   effect. Put catch-alls FIRST, specific rules LAST to override.

--

-- IMPORTANT: workspace assignments apply to ALL windows matching the class,

-- including child dialogs. Use match:modal false AND match:float false to

-- exclude transient/modal dialogs from workspace assignments.

-- =============================================================================

-- ── Modal / transient dialogs — catch ALL apps first ─────────────────────────

-- Any window that is modal (transient dialog) floats and centers regardless of

-- class. This runs FIRST (lowest priority) so app-specific rules can still

-- override. Modal = true catches Qt/GTK dialogs that set transient_for.

hl.window_rule({
    name  = "float_true_1",
    match = {
        modal = true,
    },
    float = true,
})

hl.window_rule({
    name  = "center_true_1",
    match = {
        modal = true,
    },
    center = true,
})

-- ── Default floating window size ─────────────────────────────────────────────

-- Only applies to windows that are already floating (match:float true prevents

-- this from sizing tiled windows). Specific app rules below override.

-- NOTE: "80% 80%" uses muParser expression syntax — percent of monitor size.

-- This does NOT apply to modal dialogs (they have their own intrinsic size).

hl.window_rule({
    name  = "size_80__80_",
    match = {
        float = true,
        modal = false,
    },
    size = "80% 80%",
})

