-- ── Float: file manager — centered smallish floating window ──────────────────

-- Covers Dolphin (target) and Thunar/Nemo/Nautilus alternatives.

-- Dolphin's Wayland app-ID is org.kde.dolphin — the .*dolphin.* pattern catches

-- both the Wayland app-ID and the X11 StartupWMClass.

-- Child dialogs (rename, copy, properties) have the SAME class and are also

-- matched here — they float, get centered, and we DON'T force a fixed size on

-- them so their intrinsic Qt dialog size is preserved (modal rule handles centering).

hl.window_rule({
    name  = "float_true_19",
    match = {
        class = "^(.*[Dd]olphin.*|.*[Tt]hunar.*|.*[Nn]emo.*|.*[Nn]autilus.*)$",
    },
    float = true,
})

hl.window_rule({
    name  = "center_true_7",
    match = {
        class = "^(.*[Dd]olphin.*|.*[Tt]hunar.*|.*[Nn]emo.*|.*[Nn]autilus.*)$",
    },
    center = true,
})

